DNSResult processDNSResponse() {
    // Receive DNS response
    DNSHeader header;
    if (!receiveDNSHeader(header)) {
        return DNSResult::error("Failed to receive DNS header");
    }

    // Check if full header was received
    if (!header.isComplete()) {
        return DNSResult::error("Incomplete DNS header received");
    }

    // Validate source of the response
    if (!isValidDNSServer(header.sourceIP)) {
        return DNSResult::error("DNS response from unknown server");
    }

    // Check if response ID matches a pending request
    auto pendingRequest = findPendingRequest(header.id);
    if (!pendingRequest) {
        return DNSResult::error("No pending request found for response ID");
    }

    // Process response data based on query type
    std::string resultData;
    if (pendingRequest->queryType == DNSQueryType::A) {
        resultData = processARecord(header.payload);
    } else if (pendingRequest->queryType == DNSQueryType::AAAA) {
        resultData = processAAAARecord(header.payload);
    } else if (pendingRequest->queryType == DNSQueryType::CNAME) {
        resultData = processCNAMERecord(header.payload);
    } else if (pendingRequest->queryType == DNSQueryType::PTR) {
        resultData = processPTRRecord(header.payload);
    } else {
        return DNSResult::error("Unsupported query type");
    }

    // Construct DNSResult object
    DNSResult result;
    result.id = header.id;
    result.responseData = resultData;
    result.ttl = header.ttl;
    result.originalRequest = pendingRequest;

    return result;
}

DNSResult processDNSResponse() {
    DNSResult result;
    result.status = DNS_RESULT_ERROR;

    // Simulate receiving DNS response data
    uint8_t buffer[512];
    size_t received = receiveDNSResponse(buffer, sizeof(buffer));
    if (received < sizeof(DNSHeader)) {
        result.error = "Incomplete DNS header received";
        return result;
    }

    DNSHeader* header = reinterpret_cast<DNSHeader*>(buffer);
    if (ntohs(header->id) != pendingRequestID) {
        result.error = "DNS response ID does not match any pending requests";
        return result;
    }

    if (!validateDNSServerSource(buffer, received)) {
        result.error = "DNS response from unexpected source";
        return result;
    }

    // Simulate query type and response parsing
    switch (header->queryType) {
        case DNS_QUERY_TYPE_A:
            parseARecord(buffer, received, result);
            break;
        case DNS_QUERY_TYPE_AAAA:
            parseAAAARecord(buffer, received, result);
            break;
        case DNS_QUERY_TYPE_CNAME:
            parseCNameRecord(buffer, received, result);
            break;
        case DNS_QUERY_TYPE_PTR:
            parsePTRRecord(buffer, received, result);
            break;
        default:
            result.error = "Unsupported query type";
            return result;
    }

    result.status = DNS_RESULT_SUCCESS;
    return result;
}

DNSResult processDNSResponse() {
    DNSHeader header;
    if (!receiveDNSHeader(header)) {
        return DNSResult::error("Incomplete DNS header received.");
    }

    if (header.source != expectedDNSServer) {
        return DNSResult::error("DNS response from unexpected source.");
    }

    auto pending_request = findPendingRequest(header.id);
    if (!pending_request) {
        return DNSResult::error("No pending request found for response ID.");
    }

    DNSResult result;
    result.id = header.id;
    result.original_request = *pending_request;

    if (header.type == DNSQueryType::A) {
        IPv4Address ip;
        if (parseARecord(header.data, ip)) {
            result.address_v4 = ip;
            result.ttl = header.ttl;
        } else {
            return DNSResult::error("Failed to parse A record.");
        }
    } else if (header.type == DNSQueryType::AAAA) {
        IPv6Address ip;
        if (parseAAAAResponse(header.data, ip)) {
            result.address_v6 = ip;
            result.ttl = header.ttl;
        } else {
            return DNSResult::error("Failed to parse AAAA record.");
        }
    } else if (header.type == DNSQueryType::CNAME) {
        std::string cname;
        if (parseCNameResponse(header.data, cname)) {
            result.cname = cname;
        } else {
            return DNSResult::error("Failed to parse CNAME record.");
        }
    } else if (header.type == DNSQueryType::PTR) {
        std::string hostname;
        if (parsePTRResponse(header.data, hostname)) {
            result.ptr = hostname;
        } else {
            return DNSResult::error("Failed to parse PTR record.");
        }
    } else {
        return DNSResult::error("Unsupported DNS query type.");
    }

    return result;
}

